-- Запись журнала «Новости платформы»: главная страница сайта на телефоне (30.09.2026).
INSERT INTO "PlatformNews" ("id", "title", "body", "publishedAt", "updatedAt") VALUES
    ('news_20260930_site_mobile_home',
     'Сайт: главная страница на телефоне исправлена',
     'На телефоне главная страница сайта была шире экрана: приходилось двигать её вбок, а часть блоков уходила за край. Теперь страница ровно по ширине экрана, плашки моделей в блоке «Подбор по модели автомобиля» листаются в одну строку и больше не ломают вёрстку. Остальные страницы сайта (карточка товара, каталог, корзина, контакты, доставка, поиск) на телефонной ширине проверены: там всё в порядке. Заодно длинное слово в строке поиска больше не растягивает страницу поиска.',
     '2026-09-30 21:00:00', CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;
